"""Jan-Drishti area + category authority routing.

Every configured area is represented for all 10 complaint categories.
Official emails are used where verified from government sources; Moradabad
non-police civic routing remains DEMO/TEST as requested for the hackathon.
"""

CATEGORIES = ['Road Damage', 'Garbage / Waste', 'Street Light', 'Water Supply', 'Drainage / Sewerage', 'Electricity Problem', 'Encroachment / Illegal Occupation', 'Stray Animals', 'Waterlogging / Flooding', 'Traffic / Road Safety']

AUTHORITY_CONTACTS = []

def _add(district, area, category, department, authority_name, email, *, verified, is_test, contact_level):
    AUTHORITY_CONTACTS.append({
        "district": district, "area": area, "category": category,
        "department": department, "authority_name": authority_name, "email": email,
        "verified": verified, "is_test": is_test, "contact_level": contact_level,
    })

