# ------------------------------------------------------------
# FALLBACKS — retained for safety / future areas
# ------------------------------------------------------------
DISTRICT_FALLBACKS = {
    "Bareilly": {"department": "District Administration", "authority_name": "Bareilly District Administration", "email": "dmbar@nic.in", "verified": True, "is_test": False, "contact_level": "district_admin"},
    "Bijnor": {"department": "District Administration", "authority_name": "Bijnor District Administration", "email": "dmbij@nic.in", "verified": True, "is_test": False, "contact_level": "district_admin"},
    "Moradabad": {"department": "Municipal / Local Civic Authority", "authority_name": "Moradabad DEMO Fallback", "email": "vivoslot122@gmail.com", "verified": False, "is_test": True, "contact_level": "district_demo"},
}

def _normalize(value: str | None) -> str:
    if not value:
        return ""
    return " ".join(value.strip().lower().split())

def find_authority(district: str, area: str, category: str):
    """Return exact area+category authority, then district fallback."""
    district_key = _normalize(district)
    area_key = _normalize(area)
    category_key = _normalize(category)

    for authority in AUTHORITY_CONTACTS:
        if (_normalize(authority.get('district')) == district_key
            and _normalize(authority.get('area')) == area_key
            and _normalize(authority.get('category')) == category_key):
            return authority

    for district_name, authority in DISTRICT_FALLBACKS.items():
        if _normalize(district_name) == district_key:
            return {**authority, 'district': district, 'area': area, 'category': category, 'fallback': True}

    return None

def get_authority(district: str, category: str):
    """Compatibility helper for existing GET /authority usage."""
    district_key = _normalize(district)
    category_key = _normalize(category)
    for authority in AUTHORITY_CONTACTS:
        if (_normalize(authority.get('district')) == district_key
            and _normalize(authority.get('category')) == category_key):
            return authority
    for district_name, authority in DISTRICT_FALLBACKS.items():
        if _normalize(district_name) == district_key:
            return {**authority, 'district': district, 'category': category, 'fallback': True}
    return None
